# Copy practitioner's department into Patient Encounter

if doc.practitioner:
    practitioner = frappe.get_doc("Healthcare Practitioner", doc.practitioner)
    if practitioner.department:
        doc.department = practitioner.department

import frappe

def after_submit(doc, method=None):
    plan = doc

    procedures = frappe.get_all(
        "Dental Planned Procedure",
        filters={
            "parent": plan.name,
            "planned_status": "Completed",
            "billed_invoice": ["is", "not set"]
        },
        fields=["name", "procedure_type"]
    )

    if not procedures:
        return

    invoice = frappe.new_doc("Sales Invoice")
    invoice.customer = plan.patient
    invoice.set_posting_time = 1

    for p in procedures:
        item = frappe.get_value(
            "Dental Procedure Item Map",
            {"procedure_type": p.procedure_type},
            "item"
        )

        if not item:
            frappe.throw(f"No Item mapping for {p.procedure_type}")

        invoice.append("items", {
            "item_code": item,
            "qty": 1
        })

    invoice.insert()
    invoice.submit()

    for p in procedures:
        frappe.db.set_value("Dental Planned Procedure", p.name, "billed_invoice", invoice.name)

    frappe.db.commit()
